module delivery_time_calculator (input clk, input rst_n, input start, input [31:0] misha_points [6:0], input [31:0] nadia_points [6:0], input [2:0] misha_count, input [2:0] nadia_count, output reg [31:0] result, output reg done, output reg impossible); parameter IDLE = 3'd0, SAMPLING = 3'd1, COMPUTING = 3'd2, DONE = 3'd3; reg [2:0] state; reg [31:0] sampled_misha_points [6:0]; reg [31:0] sampled_nadia_points [6:0]; reg [2:0] sampled_m_count, sampled_n_count; reg [31:0] global_min; reg [1:0] t_step, s_step; function automatic int sqrt_int(int N); int guess; if (N == 0) return 0; guess = N; guess = (guess + N / guess) >> 1; guess = (guess + N / guess) >> 1; guess = (guess + N / guess) >> 1; return guess; endfunction function automatic int compute_dx_dy(int x1, int y1, int x2, int y2); int dx, dy; dx = x2 - x1; dy = y2 - y1; return dx + dy * 32; endfunction always @(posedge clk) begin if (!rst_n) begin state <= IDLE; sampled_misha_points <= 0; sampled_nadia_points <= 0; sampled_m_count <= 0; sampled_n_count <= 0; global_min <= 0; done <= 0; impossible <= 0; end else begin case (state) IDLE: if (start) state <= SAMPLING; SAMPLING: begin sampled_misha_points <= misha_points; sampled_nadia_points <= nadia_points; sampled_m_count <= misha_count; sampled_n_count <= nadia_count; state <= COMPUTING; end COMPUTING: begin int m_dx, m_dy, n_dx, n_dy; int m_len, n_len; if (sampled_m_count > 1) begin int x1 = sampled_misha_points[0] >> 16; int y1 = sampled_misha_points[1] >> 16; int x2 = sampled_misha_points[2] >> 16; int y2 = sampled_misha_points[3] >> 16; m_dx = x2 - x1; m_dy = y2 - y1; m_len = sqrt_int(m_dx*m_dx + m_dy*m_dy) << 16; end state <= DONE; global_min <= m_len << 1; end DONE: ; endcase end end assign result = global_min; assign done = (state == DONE); assign impossible = 0; endmodule